#!/usr/bin/env node
/**
 * Tests for hooks/agent-guard.js. Zero dependencies — `node:test` on Node 18+.
 *
 *   node --test tools/agent-guard.test.mjs
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const HOOK = join(dirname(fileURLToPath(import.meta.url)), '..', 'hooks', 'agent-guard.js');

const run = (input) => {
  const r = spawnSync(process.execPath, [HOOK], {
    input: typeof input === 'string' ? input : JSON.stringify(input),
    encoding: 'utf8',
  });
  assert.equal(r.status, 0);
  return r.stdout;
};
const spawn = (tool_input) => run({ hook_event_name: 'PreToolUse', tool_name: 'Agent', tool_input });
const decision = (out) => JSON.parse(out).hookSpecificOutput;

test('no subagent_type is denied', () => {
  const d = decision(spawn({ prompt: 'x' }));
  assert.equal(d.permissionDecision, 'deny');
  assert.match(d.permissionDecisionReason, /Name the agent type/);
});

test('general-purpose, claude and Plan without a model are denied', () => {
  for (const subagent_type of ['general-purpose', 'claude', 'Plan']) {
    const d = decision(spawn({ subagent_type, prompt: 'x' }));
    assert.equal(d.permissionDecision, 'deny');
    assert.match(d.permissionDecisionReason, /pass model/);
  }
});

test('general-purpose with a model passes in silence', () => {
  assert.equal(spawn({ subagent_type: 'general-purpose', model: 'sonnet', prompt: 'x' }), '');
});

test('a kit agent and fork pass in silence', () => {
  assert.equal(spawn({ subagent_type: 'implementer', prompt: 'x' }), '');
  assert.equal(spawn({ subagent_type: 'fork', prompt: 'x' }), '');
});

test('malformed or empty input is silent', () => {
  assert.equal(run('not json'), '');
  assert.equal(run(''), '');
  assert.equal(run('{"tool_input":"x"}'), '');
});
